<?php
require 'includes/auth_helpers.php';
require 'includes/db.php';
require_staff_or_admin($pdo);
$items = $pdo->query('SELECT item_id, name, price, is_available, publish_at FROM menu_items ORDER BY name')->fetchAll();
$success = $_SESSION['flash_success'] ?? null; unset($_SESSION['flash_success']);
$pageTitle = 'Menu management'; require 'includes/header.php';
?>
<main class="container py-5"><div class="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4"><div><h1 class="mb-1">Menu management</h1><p class="text-secondary mb-0">Menu items scheduled for later appear publicly when their release time arrives.</p></div><a class="btn btn-auth" href="menu-item-edit.php">Add item</a></div>
<?php if ($success): ?><div class="alert alert-success"><?= e($success) ?></div><?php endif; ?>
<div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Item</th><th>Price</th><th>Sale status</th><th>Release</th><th></th></tr></thead><tbody>
<?php foreach ($items as $item): $available=(int)$item['is_available']===1; $releaseTime=$item['publish_at']?new DateTimeImmutable((string)$item['publish_at'],new DateTimeZone('Asia/Manila')):null; $future=$releaseTime && $releaseTime>new DateTimeImmutable('now',new DateTimeZone('Asia/Manila')); ?>
<tr><td><?= e($item['name']) ?></td><td><?= $item['price']===null?'—':'₱'.number_format((float)$item['price'],2) ?></td><td><?= $available?'Active':'Deactivated' ?></td><td><?= $item['publish_at'] ? e(date('M j, Y g:i A',strtotime($item['publish_at']))) : 'Now' ?><?= $future?' (scheduled)':'' ?></td><td class="text-end"><a class="btn btn-sm btn-outline-secondary" href="menu-item-edit.php?id=<?=(int)$item['item_id']?>">Edit</a> <?php if (($_SESSION['role']??'')==='admin'): ?><button type="button" class="btn btn-sm <?= $available?'btn-outline-danger':'btn-outline-success' ?>" data-status-item="<?=(int)$item['item_id']?>" data-status-name="<?=e($item['name'])?>" data-status="<?=$available?'deactivate':'activate'?>"><?=$available?'Deactivate':'Activate'?></button><?php endif; ?></td></tr>
<?php endforeach; ?></tbody></table></div></main>
<?php if (($_SESSION['role']??'')==='admin'): ?><div class="modal fade" id="statusConfirm" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form method="post" action="menu-item-status.php"><div class="modal-header"><h2 class="modal-title fs-5">Confirm sale status change</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><p id="status-prompt"></p><p>Type <strong id="status-required"></strong> to confirm.</p><input name="confirm_text" class="form-control" required autocomplete="off"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="item_id" id="status-item-id"><input type="hidden" name="new_status" id="status-new-status"></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-danger">Confirm change</button></div></form></div></div></div><script>document.addEventListener('DOMContentLoaded',()=>{const modal=new bootstrap.Modal('#statusConfirm');document.querySelectorAll('[data-status-item]').forEach(b=>b.addEventListener('click',()=>{const word=b.dataset.status.toUpperCase();document.getElementById('status-prompt').textContent='Change “'+b.dataset.statusName+'” to '+b.dataset.status+'?';document.getElementById('status-required').textContent=word;document.getElementById('status-item-id').value=b.dataset.statusItem;document.getElementById('status-new-status').value=b.dataset.status;document.querySelector('#statusConfirm input[name="confirm_text"]').pattern=word;modal.show();}));});</script><?php endif; ?>
<?php require 'includes/footer.php'; ?>
